test('FAP14 hostile: no lock, no package, wrong run, unknown beat, altered package all fail closed', async () => {
  // (1) no lock
  const noLock = await fplHarness.approvedEstate('fap-nolock');
  errorCode(() => production.nextAction(noLock.runDir, { scriptBuilderRoot: noLock.story.root }), 'FINAL_LOCK_MISSING');
  // (2) lock but no package
  const noPkg = await fplHarness.lockedEstate('fap-nopkg');
  errorCode(() => production.nextAction(noPkg.runDir, { scriptBuilderRoot: noPkg.story.root }), 'FINAL_ASSET_PACKAGE_MISSING');
  const e = await estateFor('hostile-basics');
  // (3) nonexistent beat
  errorCode(() => production.beatBriefing(production.context(e.runDir, e.opts), 'final-visual-999'), 'FINAL_ASSET_BEAT_UNKNOWN');
  errorCode(() => production.ingestImage(e.runDir, 'final-visual-999', makeImage('hostile-basics-img'), e.opts), 'FINAL_ASSET_BEAT_UNKNOWN');
  // (4)/(5) altered package / altered prompt
  const visual = readJson(e.paths.visual);
  visual.beats[0].final_image_prompt = `${visual.beats[0].final_image_prompt} tampered`;
  writeJson(e.paths.visual, visual);
  errorCode(() => production.nextAction(e.runDir, e.opts), 'FINAL_ASSET_PACKAGE_STALE');
});

test('FAP15 hostile: caller cannot supply authority — no fake SHA, no fabricated selection, no machine selector', async () => {
  const e = await estateFor('hostile-authority');
  const beat = e.stillBeat.final_beat_id;
  const image = makeImage('hostile-authority-img');
  const ing = production.ingestImage(e.runDir, beat, image, e.opts);
  // (6) a caller-supplied SHA is not authority: the asset hash is computed, and
  // selecting by a hash that is not a registered candidate is refused
  errorCode(() => production.selectImage(e.runDir, beat, 'f'.repeat(64), { ...e.opts, authority: HUMAN }), 'FINAL_ASSET_CANDIDATE_UNKNOWN');
  assert.equal(ing.asset.media.sha256, shaFile(image), 'the hash is computed from bytes, never accepted from the caller');
  // (12)/(13) selection requires a HUMAN authority and refuses a machine one
  errorCode(() => production.selectImage(e.runDir, beat, ing.asset.media.sha256, e.opts), 'FINAL_ASSET_HUMAN_AUTHORITY_REQUIRED');
  for (const bad of ['MACHINE_SELECTOR', 'machine', 'auto-selector', 'agent:claude', 'tool']) {
    errorCode(() => production.selectImage(e.runDir, beat, ing.asset.media.sha256, { ...e.opts, authority: bad }), 'FINAL_ASSET_HUMAN_AUTHORITY_REQUIRED');
  }
  // (11) GENERATED is never treated as SELECTED
  const status = production.beatStatus(production.context(e.runDir, e.opts), production.beatFor(production.context(e.runDir, e.opts), beat).entry);
  assert.equal(status.state, 'GENERATED');
  assert.equal(status.selected_image_sha256, null);
  assert.equal(status.complete, false);
  // (14) selected asset bytes moving invalidates the selection attempt
  const stored = path.resolve(e.runDir, ing.asset.media.path);
  fs.appendFileSync(stored, 'tampered');
  errorCode(() => production.selectImage(e.runDir, beat, ing.asset.media.sha256, { ...e.opts, authority: HUMAN }), 'FINAL_ASSET_SELECTED_HASH_MISMATCH');
});

test('FAP16 hostile: Kling authority cannot be forged, mis-sourced or escalated', async () => {
  const e = await estateFor('hostile-kling');
  const beat = e.videoBeat.final_beat_id;
  const still = e.stillBeat.final_beat_id;
  // (15) I2V before selection
  const img = makeImage('hostile-kling-img');
  const ing = production.ingestImage(e.runDir, beat, img, e.opts);
  errorCode(() => production.prepareMotionPrompt(e.runDir, beat, e.opts), 'FINAL_ASSET_I2V_REQUIRES_SELECTED_IMAGE');
  // (18) a clip without I2V authority
  const clip = makeVideo('hostile-kling-clip');
  errorCode(() => production.ingestVideo(e.runDir, beat, clip, e.opts), 'FINAL_ASSET_VIDEO_REQUIRES_SELECTED_IMAGE');
  production.selectImage(e.runDir, beat, ing.asset.media.sha256, { ...e.opts, authority: HUMAN });
  errorCode(() => production.ingestVideo(e.runDir, beat, clip, e.opts), 'FINAL_ASSET_VIDEO_REQUIRES_MOTION_PROMPT');
  // a still beat can never hold a motion prompt or a clip
  errorCode(() => production.prepareMotionPrompt(e.runDir, still, e.opts), 'FINAL_ASSET_NOT_A_VIDEO_SOURCE');
  errorCode(() => production.ingestVideo(e.runDir, still, clip, e.opts), 'FINAL_ASSET_NOT_A_VIDEO_SOURCE');
  production.prepareMotionPrompt(e.runDir, beat, e.opts);
  // (20) corrupt video
  const badVideo = path.join(media(), 'corrupt.mp4');
  fs.writeFileSync(badVideo, 'not a video at all');
  errorCode(() => production.ingestVideo(e.runDir, beat, badVideo, e.opts), 'FINAL_ASSET_VIDEO_UNREADABLE');
  // (21) selected clip bytes moving
  const vin = production.ingestVideo(e.runDir, beat, clip, e.opts);
  const storedClip = path.resolve(e.runDir, vin.asset.media.path);
  fs.appendFileSync(storedClip, 'tampered');
  errorCode(() => production.selectVideo(e.runDir, beat, vin.asset.media.sha256, { ...e.opts, authority: HUMAN }), 'FINAL_ASSET_SELECTED_HASH_MISMATCH');
  // (13) machine authority refused for clips too
  errorCode(() => production.selectVideo(e.runDir, beat, vin.asset.media.sha256, { ...e.opts, authority: 'MACHINE_SELECTOR' }), 'FINAL_ASSET_HUMAN_AUTHORITY_REQUIRED');
});

test('FAP17 hostile: asset ingest and selection never mutate the lock, package or approved Draft', async () => {
  const e = await estateFor('hostile-immutable');
  const before = {
    lock: shaFile(e.lock_path),
    pkg: shaFile(e.paths.package),
    visual: shaFile(e.paths.visual),
    performance: shaFile(e.paths.performance),
    music: shaFile(e.paths.music),
    blueprint: shaFile(e.paths.blueprint),
    draft: shaFile(path.join(e.runDir, 'media/directed-draft-assembly/directed-draft-r1.mp4')),
    review: shaFile(require('../scripts/draft-review-intake.js').reviewFile(e.runDir, 'mikko-approved')),
  };
  const beat = e.videoBeat.final_beat_id;
  const img = makeImage('hostile-immutable-img');
  const ing = production.ingestImage(e.runDir, beat, img, e.opts);
  production.selectImage(e.runDir, beat, ing.asset.media.sha256, { ...e.opts, authority: HUMAN });
  production.prepareMotionPrompt(e.runDir, beat, e.opts);
  const clip = makeVideo('hostile-immutable-clip');
  const vin = production.ingestVideo(e.runDir, beat, clip, e.opts);
  production.selectVideo(e.runDir, beat, vin.asset.media.sha256, { ...e.opts, authority: HUMAN });
  production.projectResolveAssets(e.runDir, e.opts);
  // (26)/(27)/(28) nothing upstream moved
  assert.equal(shaFile(e.lock_path), before.lock, 'lock unchanged');
  assert.equal(shaFile(e.paths.package), before.pkg, 'package unchanged');
  assert.equal(shaFile(e.paths.visual), before.visual, 'visual package unchanged');
  assert.equal(shaFile(e.paths.performance), before.performance, 'performance package unchanged');
  assert.equal(shaFile(e.paths.music), before.music, 'music brief unchanged');
  assert.equal(shaFile(e.paths.blueprint), before.blueprint, 'Resolve blueprint unchanged');
  assert.equal(shaFile(path.join(e.runDir, 'media/directed-draft-assembly/directed-draft-r1.mp4')), before.draft, 'approved Draft unchanged');
  assert.equal(shaFile(require('../scripts/draft-review-intake.js').reviewFile(e.runDir, 'mikko-approved')), before.review, 'approval unchanged');
  // (24)/(25) no publication or QC authority anywhere in the asset records
  const asset = readJson(path.resolve(e.runDir, production.beatFor(production.context(e.runDir, e.opts), beat).entry.candidates[0].record_path));
  assert.equal(asset.publication_authority, false);
  assert.equal(asset.final_asset_authority, false);
  const q = production.workQueue(e.runDir, e.opts);
  assert.equal(q.publication_approved, false);
  assert.equal(q.final_qc_pass, false);
  assert.equal(q.final_edit_complete, false);
  assert.equal(fs.existsSync(path.join(e.runDir, 'final-master.mp4')), false);
});

test('FAP18 hostile: a Draft still cannot be silently registered as a Final asset, and completion needs the real chain', async () => {
  const e = await estateFor('hostile-draft-asset');
  const beat = e.videoBeat.final_beat_id;
  // (29) a Draft bespoke still never becomes a Final asset by proximity: it is
  // not registered anywhere in the Final asset authority, and the only way any
  // file becomes a candidate is an explicit human ingest that mints a NEW
  // immutable record bound to the FINAL beat and the FINAL prompt.
  const draftStill = path.join(e.runDir, 'media', 'draft-bespoke-stills', `${e.slots[0].slot_id}.png`);
  assert.ok(fs.existsSync(draftStill), 'the Draft still exists on disk');
  const ctxBefore = production.context(e.runDir, e.opts);
  assert.equal(ctxBefore.tracker.beats.every((entry) => !(entry.candidates || []).length), true, 'no Draft asset is registered as a Final candidate');
  const draftSha = shaFile(draftStill);
  assert.equal(ctxBefore.tracker.beats.some((entry) => (entry.candidates || []).some((c) => c.sha256 === draftSha)), false);
  // and a Draft artifact that is not real publication-grade media is refused
  // outright by technical validation (this fixture's stills are placeholders)
  errorCode(() => production.ingestImage(e.runDir, beat, draftStill, e.opts), 'FINAL_ASSET_IMAGE_UNREADABLE');
  // a genuine manually generated image becomes a candidate bound to the FINAL prompt
  const img = makeImage('hostile-draft-asset-final');
  const ing = production.ingestImage(e.runDir, beat, img, e.opts);
  assert.equal(ing.asset.media_kind, 'IMAGE');
  assert.equal(ing.asset.final_beat_id, beat);
  assert.equal(ing.asset.prompt.prompt_id, e.videoBeat.final_image_prompt_id, 'bound to the FINAL prompt, not the Draft prompt');
  assert.equal(ing.asset.generation.method, 'MANUAL_GPT_IMAGE');
  assert.equal(ing.asset.selected, false);
  assert.equal(ing.asset.final_asset_authority, false);
  assert.equal(ing.beat_state, 'GENERATED', 'still only a candidate');
  // (23) completion requires the whole chain for a video beat
  production.selectImage(e.runDir, beat, ing.asset.media.sha256, { ...e.opts, authority: HUMAN });
  const status = production.beatStatus(production.context(e.runDir, e.opts), production.beatFor(production.context(e.runDir, e.opts), beat).entry);
  assert.equal(status.complete, false, 'a selected image alone never completes a video beat');
  assert.equal(status.task.task, 'PREPARE_I2V_PROMPT');
  assert.equal(production.workQueue(e.runDir, e.opts).final_assets_complete, false);
});

/* ── §27 CLI operability ─────────────────────────────────────────────────── */

test('FAP19 the CLI drives the whole loop with only a run, a beat and a file', async () => {
  const e = await estateFor('cli');
  const args = (...extra) => ['--run-id', path.basename(e.runDir), '--repo', e.repo, ...extra];
  // next: prompt exposed in human-readable form
  const next = await cli.run(args().length ? ['next', ...args()] : ['next']);
  assert.match(next.text, /NEXT TASK: GENERATE_IMAGE/);
  assert.match(next.text, /PROMPT \(final-image-prompt-final-visual-001\)/);
  assert.match(next.text, /Vertical 9:16/);
  assert.equal(next.value.final_beat_id, 'final-visual-001');
  // prompt for a specific beat
  const beat = e.stillBeat.final_beat_id;
  const prompt = await cli.run(['prompt', ...args('--beat', beat)]);
  assert.match(prompt.text, new RegExp(`BEAT ${beat}`));
  assert.equal(typeof prompt.value.prompt, 'string');
  // ingest -> the CLI tells Mikko the next exact command
  const image = makeImage('cli-image');
  const ingested = await cli.run(['ingest-image', ...args('--beat', beat, '--file', image)]);
  assert.match(ingested.text, /INGESTED final-asset-/);
  assert.match(ingested.text, /GENERATED is NOT selected/);
  assert.match(ingested.text, /Next: final-assets select-image/);
  // select by short sha prefix
  const selected = await cli.run(['select-image', ...args('--beat', beat, '--candidate', ingested.value.asset.media.sha256.slice(0, 12), '--authority', HUMAN)]);
  assert.match(selected.text, /SELECTED image/);
  assert.match(selected.text, /this still beat is now complete/);
  // queue + progress render as a table, not raw JSON
  const queue = await cli.run(['queue', ...args()]);
  assert.match(queue.text, /FINAL ASSET PRODUCTION/);
  assert.match(queue.text, /BEAT\s+STATE\s+ROLE/);
  assert.match(queue.text, /progress\s+1\/20 complete/);
  const progress = await cli.run(['progress', ...args()]);
  assert.match(progress.text, /final_complete\s+1/);
  // project
  const projected = await cli.run(['project', ...args()]);
  assert.match(projected.text, /RESOLVE ASSET PROJECTION written \(1 resolved, 19 still placeholders\)/);
  assert.match(projected.text, /blueprint mutated: false/);
  // argument hygiene: the caller may not pass a hash, asset id or authority object
  errorCode(() => cli.parseArgs(['ingest-image', '--run-id', 'x', '--beat', 'b', '--file', 'f', '--sha256', 'abc']), 'FINAL_ASSETS_ARGUMENT_INVALID');
  errorCode(() => cli.parseArgs(['select-image', '--run-id', 'x', '--beat', 'b']), 'FINAL_ASSETS_ARGUMENT_INVALID');
  errorCode(() => cli.parseArgs(['nope', '--run-id', 'x']), 'FINAL_ASSETS_COMMAND_INVALID');
  assert.match(cli.usage(), /never calls GPT Image or Kling/);
});

test('FAP20 the CLI Kling path exposes the image-bound prompt and refuses before selection', async () => {
  const e = await estateFor('cli-kling');
  const beat = e.videoBeat.final_beat_id;
  const args = (...extra) => ['--run-id', path.basename(e.runDir), '--repo', e.repo, ...extra];
  const image = makeImage('cli-kling-image');
  const ing = await cli.run(['ingest-image', ...args('--beat', beat, '--file', image)]);
  await assert.rejects(() => cli.run(['kling-prompt', ...args('--beat', beat)]), (error) => error.code === 'FINAL_ASSET_I2V_REQUIRES_SELECTED_IMAGE');
  await cli.run(['select-image', ...args('--beat', beat, '--candidate', ing.value.asset.media.sha256.slice(0, 12), '--authority', HUMAN)]);
  const kling = await cli.run(['kling-prompt', ...args('--beat', beat)]);
  assert.match(kling.text, /KLING PROMPT — beat/);
  assert.match(kling.text, new RegExp(`image sha256   ${shaFile(image)}`));
  assert.match(kling.text, /do not allow:/);
  assert.equal(kling.value.source_image.sha256, shaFile(image));
  const clip = makeVideo('cli-kling-clip');
  const vin = await cli.run(['ingest-video', ...args('--beat', beat, '--file', clip)]);
  assert.match(vin.text, /VIDEO_GENERATED is NOT selected/);
  const vsel = await cli.run(['select-video', ...args('--beat', beat, '--candidate', vin.value.asset.media.sha256.slice(0, 12), '--authority', HUMAN)]);
  assert.match(vsel.text, /SELECTED final clip/);
  assert.match(vsel.text, /provenance  source image/);
});

test('FAP21 the state machine keeps GENERATED, SELECTED_IMAGE and FINAL_ASSET_SELECTED distinct', async () => {
  assert.deepEqual(production.BEAT_STATES, ['PROMPT_READY', 'GENERATED', 'SELECTED_IMAGE', 'I2V_READY', 'VIDEO_GENERATED', 'FINAL_ASSET_SELECTED', 'BLOCKED']);
  assert.deepEqual(production.DISPOSITIONS, ['CANDIDATE', 'KEEP_AS_ALTERNATE', 'REJECTED', 'SELECTED', 'SUPERSEDED']);
  // the historical spelling still reads correctly
  assert.equal(production.normalizedState({ state: 'SELECTED' }), 'SELECTED_IMAGE');
  assert.equal(production.normalizedState({ state: 'GENERATED' }), 'GENERATED');
  const e = await estateFor('states');
  const video = e.videoBeat.final_beat_id;
  const img = makeImage('states-img');
  const ing = production.ingestImage(e.runDir, video, img, e.opts);
  assert.equal(ing.beat_state, 'GENERATED');
  const sel = production.selectImage(e.runDir, video, ing.asset.media.sha256, { ...e.opts, authority: HUMAN });
  assert.equal(sel.state, 'SELECTED_IMAGE');
  assert.notEqual(sel.state, 'FINAL_ASSET_SELECTED', 'a video beat is not complete on a selected image');
  // and the promoted package resolver still understands the run
  const legacy = pkgAuthority.nextActions(e.runDir, e.opts);
  assert.ok(legacy.ready.length + legacy.waiting_on_mikko.length > 0);
  assert.equal(legacy.publication_approved, false);
});

